    inverse_block_order = torch.tensor(
        [0, 4, 1, 5, 2, 6, 3, 7], dtype=torch.long, device=tensor.device
    )
    shape = tensor.shape
    return (
        tensor.view(shape[0], shape[1] // 128, 8, 16, shape[2])
        .index_select(2, inverse_block_order)
        .reshape(shape)
    )


