        ctk = request.chat_template_kwargs or {}
        thinking_toggles = (ctk.get("enable_thinking"), ctk.get("thinking"))
        if any(toggle is False for toggle in thinking_toggles):
            return False
        if any(toggle is True for toggle in thinking_toggles):
            return True
